// @FIGURE_CODE_BEGIN
// panel groups → THREE.Group for 1D, 2D, 3D dimension views
// axes → black Line segments plus ConeGeometry arrowheads
// origin dot → SphereGeometry(0.07) black
// 1D hyperplane marker → thin translucent BoxGeometry slab at x1=0
// 2D hyperplanes → translucent thick rectangle strips clipped to square domain
// 2D half-space shading → translucent clipped BufferGeometry polygons
// 3D hyperplanes → translucent double-sided BufferGeometry polygons clipped to cube
// draggable input point → SphereGeometry(0.09) black
// dashed guides → LineDashedMaterial guide polylines from input point to reference planes/axes
// selected normal → ArrowHelper colored by selected hyperplane
// labels/badges → addLabel HTML labels for axes, signs, equation, class, panel letter

const fig = {
  dim: '3D',
  selected: 'teal',
  alpha: 0,
  p: new THREE.Vector3(0.8, 0.7, 0.6),
  L: 2.2,
  axisL: 3,
  colors: { teal: 0x9bd8d4, orange: 0xd4835f, gray: 0xc6ced0 },
  css: { teal: '#9bd8d4', orange: '#d4835f', gray: '#c6ced0' }
};

const root = new THREE.Group();
scene.add(root);
const group1 = new THREE.Group();
const group2 = new THREE.Group();
const group3 = new THREE.Group();
root.add(group1, group2, group3);

function matLine(color = 0x000000) {
  return new THREE.LineBasicMaterial({ color });
}

function addAxis(group, start, end, opts = {}) {
  const s = new THREE.Vector3(...start), e = new THREE.Vector3(...end);
  const dir = e.clone().sub(s).normalize();
  const geom = new THREE.BufferGeometry().setFromPoints([s, e]);
  const line = new THREE.Line(geom, matLine(0x000000));
  group.add(line);
  const headLen = opts.headLen ?? 0.18;
  const headRad = opts.headRad ?? 0.055;
  function coneAt(pos, dvec) {
    const cone = new THREE.Mesh(
      new THREE.ConeGeometry(headRad, headLen, 24),
      new THREE.MeshBasicMaterial({ color: 0x000000 })
    );
    cone.position.copy(pos).add(dvec.clone().multiplyScalar(-headLen / 2));
    cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dvec.clone().normalize());
    group.add(cone);
  }
  coneAt(e, dir);
  if (opts.bidir) coneAt(s, dir.clone().negate());
  return line;
}

function addOrigin(group) {
  const m = new THREE.Mesh(
    new THREE.SphereGeometry(0.07, 28, 16),
    new THREE.MeshBasicMaterial({ color: 0x000000 })
  );
  group.add(m);
  return m;
}

addAxis(group1, [-fig.axisL, 0, 0], [fig.axisL, 0, 0], { bidir: true });
addOrigin(group1);
const marker1D = new THREE.Mesh(
  new THREE.BoxGeometry(0.08, 0.9, 0.02),
  new THREE.MeshBasicMaterial({ color: fig.colors.teal, transparent: true, opacity: 0.75, depthWrite: false })
);
group1.add(marker1D);
registerInteractive(marker1D, {
  title: '1D hyperplane',
  tooltip: 'Threshold point',
  body: 'In one input dimension, w₁x₁+b=0 is a single point on the number line.'
});

addAxis(group2, [-fig.axisL, 0, 0], [fig.axisL, 0, 0], { bidir: true });
addAxis(group2, [0, -fig.axisL, 0], [0, fig.axisL, 0], { bidir: true });
addOrigin(group2);

addAxis(group3, [-fig.axisL, 0, 0], [fig.axisL, 0, 0], { bidir: true });
addAxis(group3, [0, -fig.axisL, 0], [0, fig.axisL, 0], { bidir: true });
addAxis(group3, [0, 0, 0], [0, 0, fig.axisL], { bidir: false });
addOrigin(group3);

const stripMatTeal = new THREE.MeshBasicMaterial({ color: fig.colors.teal, transparent: true, opacity: 0.82, side: THREE.DoubleSide, depthWrite: false });
const stripMatOrange = new THREE.MeshBasicMaterial({ color: fig.colors.orange, transparent: true, opacity: 0.82, side: THREE.DoubleSide, depthWrite: false });
const line2D = {
  teal: new THREE.Mesh(new THREE.BufferGeometry(), stripMatTeal),
  orange: new THREE.Mesh(new THREE.BufferGeometry(), stripMatOrange)
};
group2.add(line2D.teal, line2D.orange);

const shadePos = new THREE.Mesh(new THREE.BufferGeometry(), new THREE.MeshBasicMaterial({ color: 0x9bd8d4, transparent: true, opacity: 0.13, side: THREE.DoubleSide, depthWrite: false }));
const shadeNeg = new THREE.Mesh(new THREE.BufferGeometry(), new THREE.MeshBasicMaterial({ color: 0x444444, transparent: true, opacity: 0.055, side: THREE.DoubleSide, depthWrite: false }));
group2.add(shadePos, shadeNeg);

const planeMats = {
  teal: new THREE.MeshBasicMaterial({ color: fig.colors.teal, transparent: true, opacity: 0.65, side: THREE.DoubleSide, depthWrite: false }),
  orange: new THREE.MeshBasicMaterial({ color: fig.colors.orange, transparent: true, opacity: 0.75, side: THREE.DoubleSide, depthWrite: false }),
  gray: new THREE.MeshBasicMaterial({ color: fig.colors.gray, transparent: true, opacity: 0.70, side: THREE.DoubleSide, depthWrite: false })
};
const planes3D = {
  teal: new THREE.Mesh(new THREE.BufferGeometry(), planeMats.teal),
  orange: new THREE.Mesh(new THREE.BufferGeometry(), planeMats.orange),
  gray: new THREE.Mesh(new THREE.BufferGeometry(), planeMats.gray)
};
planes3D.gray.renderOrder = 0;
planes3D.teal.renderOrder = 1;
planes3D.orange.renderOrder = 2;
group3.add(planes3D.gray, planes3D.teal, planes3D.orange);

for (const [name, obj] of Object.entries({ ...line2D, ...planes3D, marker1D })) {
  registerInteractive(obj, {
    title: `${name === 'marker1D' ? 'teal' : name} neuron boundary`,
    tooltip: 'Click to select this hyperplane',
    body: 'The weight vector is normal to this zero set. Changing the selected weight component rotates only this boundary.',
    onClick: () => selectHyperplane(name === 'marker1D' ? 'teal' : name)
  });
}

const pointMesh = new THREE.Mesh(
  new THREE.SphereGeometry(0.09, 32, 18),
  new THREE.MeshBasicMaterial({ color: 0x000000 })
);
root.add(pointMesh);
registerInteractive(pointMesh, {
  title: 'Input point x',
  tooltip: 'Drag the input point',
  body: 'Moving x changes the sign of each neuron pre-activation wⱼᵀx+bⱼ.'
});

const guideMat = new THREE.LineDashedMaterial({ color: 0x000000, dashSize: 0.12, gapSize: 0.08 });
const guides = [];
for (let i = 0; i < 4; i++) {
  const l = new THREE.Line(new THREE.BufferGeometry(), guideMat);
  guides.push(l);
  root.add(l);
}

const normalArrow = new THREE.ArrowHelper(new THREE.Vector3(1, 0, 0), new THREE.Vector3(0, 0, 0), 1.05, fig.colors.teal, 0.18, 0.08);
root.add(normalArrow);

function normalOf(name) {
  const a = (name === fig.selected) ? fig.alpha : 0;
  if (name === 'teal') return new THREE.Vector3(1, a, 0).normalize();
  if (name === 'orange') return new THREE.Vector3(a, 1, 0).normalize();
  return new THREE.Vector3(a, 0, 1).normalize();
}

function selectedNormalRaw() {
  const a = fig.alpha;
  if (fig.selected === 'teal') return [1, a, 0];
  if (fig.selected === 'orange') return [a, 1, 0];
  return [a, 0, 1];
}

function planePolyInCube(n, L) {
  const pts = [];
  const verts = [];
  for (const x of [-L, L]) for (const y of [-L, L]) for (const z of [-L, L]) verts.push(new THREE.Vector3(x, y, z));
  const edges = [[0,1],[0,2],[0,4],[3,1],[3,2],[3,7],[5,1],[5,4],[5,7],[6,2],[6,4],[6,7]];
  for (const [i, j] of edges) {
    const a = verts[i], b = verts[j];
    const da = n.dot(a), db = n.dot(b);
    if (Math.abs(da) < 1e-7) pts.push(a.clone());
    if (da * db < 0) pts.push(a.clone().lerp(b, da / (da - db)));
    if (Math.abs(db) < 1e-7) pts.push(b.clone());
  }
  const unique = [];
  for (const p of pts) if (!unique.some(q => q.distanceToSquared(p) < 1e-8)) unique.push(p);
  if (unique.length < 3) return new THREE.BufferGeometry();
  const c = unique.reduce((acc, p) => acc.add(p), new THREE.Vector3()).multiplyScalar(1 / unique.length);
  const u = unique[0].clone().sub(c).normalize();
  const v = new THREE.Vector3().crossVectors(n, u).normalize();
  unique.sort((p, q) => Math.atan2(p.clone().sub(c).dot(v), p.clone().sub(c).dot(u)) - Math.atan2(q.clone().sub(c).dot(v), q.clone().sub(c).dot(u)));
  const positions = [];
  for (let i = 1; i < unique.length - 1; i++) positions.push(...unique[0].toArray(), ...unique[i].toArray(), ...unique[i + 1].toArray());
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  g.computeVertexNormals();
  return g;
}

function lineStrip2DGeom(n, L, width) {
  const pts = [];
  const corners = [new THREE.Vector2(-L,-L), new THREE.Vector2(L,-L), new THREE.Vector2(L,L), new THREE.Vector2(-L,L)];
  for (let i = 0; i < 4; i++) {
    const a = corners[i], b = corners[(i + 1) % 4];
    const da = n.x * a.x + n.y * a.y, db = n.x * b.x + n.y * b.y;
    if (Math.abs(da) < 1e-7) pts.push(a.clone());
    if (da * db < 0) pts.push(a.clone().lerp(b, da / (da - db)));
    if (Math.abs(db) < 1e-7) pts.push(b.clone());
  }
  const unique = [];
  for (const p of pts) if (!unique.some(q => q.distanceToSquared(p) < 1e-8)) unique.push(p);
  if (unique.length < 2) return new THREE.BufferGeometry();
  const a = unique[0], b = unique[1];
  const dir = b.clone().sub(a).normalize();
  const perp = new THREE.Vector2(-dir.y, dir.x).multiplyScalar(width / 2);
  const p0 = a.clone().add(perp), p1 = b.clone().add(perp), p2 = b.clone().sub(perp), p3 = a.clone().sub(perp);
  const positions = [p0.x,p0.y,0, p1.x,p1.y,0, p2.x,p2.y,0, p0.x,p0.y,0, p2.x,p2.y,0, p3.x,p3.y,0];
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  return g;
}

function clipHalfPlane2D(n, L, positive) {
  let poly = [new THREE.Vector2(-L,-L), new THREE.Vector2(L,-L), new THREE.Vector2(L,L), new THREE.Vector2(-L,L)];
  const inside = p => positive ? (n.x * p.x + n.y * p.y >= -1e-8) : (n.x * p.x + n.y * p.y <= 1e-8);
  const out = [];
  for (let i = 0; i < poly.length; i++) {
    const a = poly[i], b = poly[(i + 1) % poly.length];
    const ina = inside(a), inb = inside(b);
    if (ina && inb) out.push(b);
    else if (ina && !inb) {
      const da = n.x * a.x + n.y * a.y, db = n.x * b.x + n.y * b.y;
      out.push(a.clone().lerp(b, da / (da - db)));
    } else if (!ina && inb) {
      const da = n.x * a.x + n.y * a.y, db = n.x * b.x + n.y * b.y;
      out.push(a.clone().lerp(b, da / (da - db)), b);
    }
  }
  poly = out;
  if (poly.length < 3) return new THREE.BufferGeometry();
  const positions = [];
  for (let i = 1; i < poly.length - 1; i++) positions.push(poly[0].x,poly[0].y,-0.015, poly[i].x,poly[i].y,-0.015, poly[i+1].x,poly[i+1].y,-0.015);
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  return g;
}

function replaceGeom(obj, geom) {
  obj.geometry.dispose();
  obj.geometry = geom;
  if (obj.geometry.computeBoundingSphere) obj.geometry.computeBoundingSphere();
}

function updateGuides() {
  const p = displayPoint();
  const sets = [];
  if (fig.dim === '1D') {
    sets.push([p, new THREE.Vector3(0, 0, 0)]);
  } else if (fig.dim === '2D') {
    sets.push([p, new THREE.Vector3(p.x, 0, 0)]);
    sets.push([p, new THREE.Vector3(0, p.y, 0)]);
    sets.push([p, new THREE.Vector3(0, 0, 0)]);
  } else {
    sets.push([p, new THREE.Vector3(p.x, p.y, 0)]);
    sets.push([p, new THREE.Vector3(p.x, 0, p.z)]);
    sets.push([p, new THREE.Vector3(0, p.y, p.z)]);
    sets.push([new THREE.Vector3(0, 0, 0), p]);
  }
  for (let i = 0; i < guides.length; i++) {
    guides[i].visible = i < sets.length;
    if (i < sets.length) {
      replaceGeom(guides[i], new THREE.BufferGeometry().setFromPoints(sets[i]));
      guides[i].computeLineDistances();
    }
  }
}

function displayPoint() {
  if (fig.dim === '1D') return new THREE.Vector3(fig.p.x, 0, 0);
  if (fig.dim === '2D') return new THREE.Vector3(fig.p.x, fig.p.y, 0);
  return fig.p.clone();
}

function valueFor(name) {
  return normalOf(name).dot(displayPoint());
}

function updateGeometry() {
  const nTeal = normalOf('teal'), nOrange = normalOf('orange'), nGray = normalOf('gray');
  replaceGeom(line2D.teal, lineStrip2DGeom(nTeal, fig.L, 0.105));
  replaceGeom(line2D.orange, lineStrip2DGeom(nOrange, fig.L, 0.105));
  const ns = normalOf(fig.selected);
  replaceGeom(shadePos, clipHalfPlane2D(new THREE.Vector2(ns.x, ns.y).normalize(), fig.L, true));
  replaceGeom(shadeNeg, clipHalfPlane2D(new THREE.Vector2(ns.x, ns.y).normalize(), fig.L, false));
  replaceGeom(planes3D.teal, planePolyInCube(nTeal, fig.L));
  replaceGeom(planes3D.orange, planePolyInCube(nOrange, fig.L));
  replaceGeom(planes3D.gray, planePolyInCube(nGray, fig.L));
  pointMesh.position.copy(displayPoint());
  updateGuides();
  const narr = normalOf(fig.selected);
  normalArrow.position.set(0, 0, 0);
  normalArrow.setDirection(narr);
  normalArrow.setLength(1.05, 0.18, 0.08);
  normalArrow.setColor(new THREE.Color(fig.colors[fig.selected]));
}

const labels = {};
function makeLabel(key, html, pos, opt) { labels[key] = addLabel(html, pos, opt); }
setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, rollDeg: 0, heightFraction: 0.72 });
makeLabel('panel', 'c)', new THREE.Vector3(-2.85, 2.65, 0), { fontSize: '30px', offset: [-18, -10] });
makeLabel('x1', '<i>x</i><sub>1</sub>', new THREE.Vector3(3.18, 0, 0), { fontSize: '28px', offset: [8, 8] });
makeLabel('x2', '<i>x</i><sub>2</sub>', new THREE.Vector3(0, 3.18, 0), { fontSize: '28px', offset: [8, -8] });
makeLabel('x3', '<i>x</i><sub>3</sub>', new THREE.Vector3(0, 0, 3.18), { fontSize: '28px', offset: [-6, 8] });
makeLabel('point', '<i>x</i>', displayPoint().clone().add(new THREE.Vector3(0.12, 0.15, 0.12)), { fontSize: '16px', bold: true });
makeLabel('eq', '', new THREE.Vector3(-1.7, 2.35, -1.7), { fontSize: '14px', background: 'rgba(255,255,255,0.75)' });
makeLabel('class', '', new THREE.Vector3(1.55, 2.45, -1.5), { fontSize: '15px', bold: true, background: 'rgba(255,255,255,0.82)' });
makeLabel('sTeal', '', new THREE.Vector3(0.12, 1.75, -1.65), { fontSize: '12px', background: 'rgba(155,216,212,0.55)' });
makeLabel('sOrange', '', new THREE.Vector3(1.65, 0.15, -1.65), { fontSize: '12px', background: 'rgba(212,131,95,0.48)' });
makeLabel('sGray', '', new THREE.Vector3(1.7, 1.65, 0.12), { fontSize: '12px', background: 'rgba(198,206,208,0.6)' });

function setLabelVisibility() {
  labels.x2.div.style.visibility = fig.dim === '1D' ? 'hidden' : 'visible';
