function planePolyInCube(n, L) {
  const pts = [];
  const verts = [];
  for (const x of [-L, L]) for (const y of [-L, L]) for (const z of [-L, L]) verts.push(new THREE.Vector3(x, y, z));
  const edges = [[0,1],[0,2],[0,4],[3,1],[3,2],[3,7],[5,1],[5,4],[5,7],[6,2],[6,4],[6,7]];
  for (const [i, j] of edges) {
    const a = verts[i], b = verts[j];
    const da = n.dot(a), db = n.dot(b);
    if (Math.abs(da) < 1e-7) pts.push(a.clone());
    if (da * db < 0) pts.push(a.clone().lerp(b, da / (da - db)));
    if (Math.abs(db) < 1e-7) pts.push(b.clone());
  }
  const unique = [];
  for (const p of pts) if (!unique.some(q => q.distanceToSquared(p) < 1e-8)) unique.push(p);
  if (unique.length < 3) return new THREE.BufferGeometry();
  const c = unique.reduce((acc, p) => acc.add(p), new THREE.Vector3()).multiplyScalar(1 / unique.length);
  const u = unique[0].clone().sub(c).normalize();
  const v = new THREE.Vector3().crossVectors(n, u).normalize();
  unique.sort((p, q) => Math.atan2(p.clone().sub(c).dot(v), p.clone().sub(c).dot(u)) - Math.atan2(q.clone().sub(c).dot(v), q.clone().sub(c).dot(u)));
  const positions = [];
  for (let i = 1; i < unique.length - 1; i++) positions.push(...unique[0].toArray(), ...unique[i].toArray(), ...unique[i + 1].toArray());
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  g.computeVertexNormals();
  return g;
}

function lineStrip2DGeom(n, L, width) {
  const pts = [];
  const corners = [new THREE.Vector2(-L,-L), new THREE.Vector2(L,-L), new THREE.Vector2(L,L), new THREE.Vector2(-L,L)];
  for (let i = 0; i < 4; i++) {
    const a = corners[i], b = corners[(i + 1) % 4];
    const da = n.x * a.x + n.y * a.y, db = n.x * b.x + n.y * b.y;
    if (Math.abs(da) < 1e-7) pts.push(a.clone());
    if (da * db < 0) pts.push(a.clone().lerp(b, da / (da - db)));
    if (Math.abs(db) < 1e-7) pts.push(b.clone());
  }
  const unique = [];
  for (const p of pts) if (!unique.some(q => q.distanceToSquared(p) < 1e-8)) unique.push(p);
  if (unique.length < 2) return new THREE.BufferGeometry();
  const a = unique[0], b = unique[1];
  const dir = b.clone().sub(a).normalize();
  const perp = new THREE.Vector2(-dir.y, dir.x).multiplyScalar(width / 2);
  const p0 = a.clone().add(perp), p1 = b.clone().add(perp), p2 = b.clone().sub(perp), p3 = a.clone().sub(perp);
  const positions = [p0.x,p0.y,0, p1.x,p1.y,0, p2.x,p2.y,0, p0.x,p0.y,0, p2.x,p2.y,0, p3.x,p3.y,0];
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  return g;
}

function clipHalfPlane2D(n, L, positive) {
  let poly = [new THREE.Vector2(-L,-L), new THREE.Vector2(L,-L), new THREE.Vector2(L,L), new THREE.Vector2(-L,L)];
  const inside = p => positive ? (n.x * p.x + n.y * p.y >= -1e-8) : (n.x * p.x + n.y * p.y <= 1e-8);
  const out = [];
  for (let i = 0; i < poly.length; i++) {
    const a = poly[i], b = poly[(i + 1) % poly.length];
    const ina = inside(a), inb = inside(b);
    if (ina && inb) out.push(b);
    else if (ina && !inb) {
      const da = n.x * a.x + n.y * a.y, db = n.x * b.x + n.y * b.y;
      out.push(a.clone().lerp(b, da / (da - db)));
    } else if (!ina && inb) {
      const da = n.x * a.x + n.y * a.y, db = n.x * b.x + n.y * b.y;
      out.push(a.clone().lerp(b, da / (da - db)), b);
    }
  }
  poly = out;
  if (poly.length < 3) return new THREE.BufferGeometry();
  const positions = [];
  for (let i = 1; i < poly.length - 1; i++) positions.push(poly[0].x,poly[0].y,-0.015, poly[i].x,poly[i].y,-0.015, poly[i+1].x,poly[i+1].y,-0.015);
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  return g;
}

function replaceGeom(obj, geom) {
  obj.geometry.dispose();
  obj.geometry = geom;
