}

function updateGuides() {
  const p = displayPoint();
  const sets = [];
  if (fig.dim === '1D') {
    sets.push([p, new THREE.Vector3(0, 0, 0)]);
  } else if (fig.dim === '2D') {
    sets.push([p, new THREE.Vector3(p.x, 0, 0)]);
    sets.push([p, new THREE.Vector3(0, p.y, 0)]);
    sets.push([p, new THREE.Vector3(0, 0, 0)]);
  } else {
    sets.push([p, new THREE.Vector3(p.x, p.y, 0)]);
    sets.push([p, new THREE.Vector3(p.x, 0, p.z)]);
    sets.push([p, new THREE.Vector3(0, p.y, p.z)]);
    sets.push([new THREE.Vector3(0, 0, 0), p]);
  }
  for (let i = 0; i < guides.length; i++) {
    guides[i].visible = i < sets.length;
    if (i < sets.length) {
      replaceGeom(guides[i], new THREE.BufferGeometry().setFromPoints(sets[i]));
      guides[i].computeLineDistances();
    }
  }
}

