const dragRay = new THREE.Raycaster();
const ndc = new THREE.Vector2();
let dragging = false;
let dragPlane = new THREE.Plane();
let dragStartHit = new THREE.Vector3();
let dragStartP = new THREE.Vector3();

function pointerNDC(ev) {
  const r = canvas.getBoundingClientRect();
  ndc.x = ((ev.clientX - r.left) / r.width) * 2 - 1;
  ndc.y = -((ev.clientY - r.top) / r.height) * 2 + 1;
}

canvas.addEventListener('pointerdown', ev => {
  pointerNDC(ev);
  dragRay.setFromCamera(ndc, camera);
  const hits = dragRay.intersectObject(pointMesh, false);
  if (!hits.length) return;
  dragging = true;
  controls.enabled = false;
  dragStartP.copy(fig.p);
  if (fig.dim === '3D') {
    const camDir = new THREE.Vector3();
    camera.getWorldDirection(camDir);
    dragPlane.setFromNormalAndCoplanarPoint(camDir, pointMesh.position);
  } else {
    dragPlane.setFromNormalAndCoplanarPoint(new THREE.Vector3(0, 0, 1), new THREE.Vector3(0, 0, 0));
  }
  dragRay.ray.intersectPlane(dragPlane, dragStartHit);
  ev.preventDefault();
});

window.addEventListener('pointermove', ev => {
  if (!dragging) return;
  pointerNDC(ev);
  dragRay.setFromCamera(ndc, camera);
  const hit = new THREE.Vector3();
  if (!dragRay.ray.intersectPlane(dragPlane, hit)) return;
  const delta = hit.sub(dragStartHit);
  const q = dragStartP.clone().add(delta);
  q.x = THREE.MathUtils.clamp(q.x, -2.05, 2.05);
  q.y = THREE.MathUtils.clamp(q.y, -2.05, 2.05);
  q.z = THREE.MathUtils.clamp(q.z, -2.05, 2.05);
  if (fig.dim === '1D') { q.y = fig.p.y; q.z = fig.p.z; }
  if (fig.dim === '2D') { q.z = fig.p.z; }
  fig.p.copy(q);
  refresh(false);
});

window.addEventListener('pointerup', () => {
  if (dragging) {
    dragging = false;
    controls.enabled = true;
  }
});

refresh(true);
goToStep(3);
