// @FIGURE_CODE_BEGIN
// panel containers → THREE.Group for simultaneous a), b), c) views
// axes → black Line segments plus ConeGeometry arrowheads; dashed Line segments only where source shows hidden axes
// origin dots → SphereGeometry black at the zero threshold/origin in each panel
// 1D hyperplane → thin vertical teal BoxGeometry slab on the x1 number line
// 2D hyperplanes → thin teal vertical strip and orange horizontal strip in the x1-x2 plane
// 3D gray hyperplane → large translucent rectangle parallel to x1-x2, behind the axes
// 3D teal hyperplane → translucent vertical parallelogram spanning x2 and x3
// 3D orange hyperplane → translucent horizontal parallelogram spanning x1 and x3
// labels → addLabel HTML labels for panel letters and axis names only

const source = {
  selected: 'teal',
  layout: 'all',
  slopes: { teal: 0, orange: 0, gray: 0 },
  colors: {
    teal: 0x9fd9d6,
    orange: 0xd58461,
    gray: 0xc8d0d2,
    black: 0x000000
  },
  css: {
    teal: '#9fd9d6',
    orange: '#d58461',
    gray: '#c8d0d2'
  }
};

const root = new THREE.Group();
scene.add(root);

const panelA = new THREE.Group();
const panelB = new THREE.Group();
const panelC = new THREE.Group();
panelA.position.set(-4.55, 0, 0);
panelB.position.set(-1.35, 0, 0);
panelC.position.set(2.35, 0, 0);
root.add(panelA, panelB, panelC);

function lineMaterial({ dashed = false, color = 0x000000, opacity = 1 } = {}) {
  const mat = dashed
    ? new THREE.LineDashedMaterial({ color, dashSize: 0.075, gapSize: 0.055, transparent: opacity < 1, opacity })
    : new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity });
  mat.depthTest = false;
  mat.depthWrite = false;
  return mat;
}

function meshMaterial(color, opacity = 1) {
  return new THREE.MeshBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    side: THREE.DoubleSide,
    depthWrite: false,
    depthTest: true
  });
}

function addLine(group, pts, opts = {}) {
  const geom = new THREE.BufferGeometry().setFromPoints(pts.map(p => new THREE.Vector3(...p)));
  const line = new THREE.Line(geom, lineMaterial(opts));
  line.renderOrder = opts.renderOrder ?? 10;
  if (opts.dashed) line.computeLineDistances();
  group.add(line);
  return line;
}

function addConeArrow(group, pos, dir, opts = {}) {
  const dvec = new THREE.Vector3(...dir).normalize();
  const cone = new THREE.Mesh(
    new THREE.ConeGeometry(opts.radius ?? 0.045, opts.length ?? 0.16, 24),
    new THREE.MeshBasicMaterial({ color: opts.color ?? 0x000000, depthTest: false, depthWrite: false })
  );
  cone.position.copy(new THREE.Vector3(...pos)).add(dvec.clone().multiplyScalar(-(opts.length ?? 0.16) / 2));
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dvec);
  cone.renderOrder = opts.renderOrder ?? 11;
  group.add(cone);
  return cone;
}

function addAxis(group, start, end, opts = {}) {
  addLine(group, [start, end], opts);
  const s = new THREE.Vector3(...start);
  const e = new THREE.Vector3(...end);
  const dir = e.clone().sub(s).normalize();
  addConeArrow(group, end, dir, opts);
  if (opts.bidir) addConeArrow(group, start, dir.clone().negate().toArray(), opts);
}

function addDot(group, pos = [0, 0, 0], r = 0.055) {
  const dot = new THREE.Mesh(
    new THREE.SphereGeometry(r, 32, 16),
    new THREE.MeshBasicMaterial({ color: 0x000000, depthTest: false, depthWrite: false })
  );
  dot.position.set(...pos);
  dot.renderOrder = 20;
  group.add(dot);
  registerInteractive(dot, {
    title: 'Origin / threshold',
    tooltip: 'Neuron threshold point',
    body: 'The black dot marks the zero threshold. In 1D it is a point; in 2D and 3D the colored zero sets pass through it.'
  });
  return dot;
}

function rectGeom(vertices) {
  const p = [];
  const idx = [0, 1, 2, 0, 2, 3];
  for (const i of idx) p.push(vertices[i].x, vertices[i].y, vertices[i].z);
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(p, 3));
  g.computeVertexNormals();
  g.computeBoundingBox();
  g.computeBoundingSphere();
  return g;
}

function replaceGeom(mesh, geom) {
  mesh.geometry?.dispose?.();
  mesh.geometry = geom;
}

function localPos(group, x, y, z = 0) {
  return group.localToWorld(new THREE.Vector3(x, y, z));
}

/* panel a */
addAxis(panelA, [-1.28, 0, 0], [1.28, 0, 0], { bidir: true });
