function updatePanelBGeometry() {
  const aT = source.slopes.teal;
  const aO = source.slopes.orange;
  const h = 0.92, w = 0.035, L = 0.92;

  const tealVerts = [
    new THREE.Vector3(aT * -h - w, -h, 0.012),
    new THREE.Vector3(aT * h - w, h, 0.012),
    new THREE.Vector3(aT * h + w, h, 0.012),
    new THREE.Vector3(aT * -h + w, -h, 0.012)
  ];
  const orangeVerts = [
    new THREE.Vector3(-L, aO * -L - w, 0.018),
    new THREE.Vector3(L, aO * L - w, 0.018),
    new THREE.Vector3(L, aO * L + w, 0.018),
    new THREE.Vector3(-L, aO * -L + w, 0.018)
  ];

  replaceGeom(stripBTeal, rectGeom(tealVerts));
  replaceGeom(stripBOrange, rectGeom(orangeVerts));
}

function updatePanelCGeometry() {
  const aT = source.slopes.teal;
  const aO = source.slopes.orange;
  const aG = source.slopes.gray;

  const gray = [
    new THREE.Vector3(-1.05, -1.02, -0.34 + aG * -1.05),
    new THREE.Vector3(1.05, -1.02, -0.34 + aG * 1.05),
    new THREE.Vector3(1.05, 1.02, -0.34 + aG * 1.05),
    new THREE.Vector3(-1.05, 1.02, -0.34 + aG * -1.05)
  ];

  const teal = [
    new THREE.Vector3(aT * -1.22, -1.22, 1.04),
    new THREE.Vector3(aT * 1.22, 1.22, 1.04),
    new THREE.Vector3(aT * 1.22, 1.22, -0.92),
    new THREE.Vector3(aT * -1.22, -1.22, -0.92)
  ];

  const orange = [
    new THREE.Vector3(-1.42, aO * -1.42, 0.86),
    new THREE.Vector3(1.42, aO * 1.42, 0.86),
    new THREE.Vector3(1.42, aO * 1.42, -0.88),
    new THREE.Vector3(-1.42, aO * -1.42, -0.88)
  ];

  replaceGeom(planeGray, rectGeom(gray));
  replaceGeom(planeTeal, rectGeom(teal));
  replaceGeom(planeOrange, rectGeom(orange));
}

function refreshGeometry() {
  updatePanelBGeometry();
  updatePanelCGeometry();
}

refreshGeometry();

for (const [name, obj] of [
  ['teal', slabA],
  ['teal', stripBTeal],
  ['orange', stripBOrange],
  ['gray', planeGray],
