  ['orange', planeOrange]
]) {
  registerInteractive(obj, {
    title: `${name[0].toUpperCase()}${name.slice(1)} hyperplane`,
    tooltip: `Click to select the ${name} hyperplane`,
    body: 'A neuron hyperplane is the set of inputs where its pre-activation is zero. Use the tilt slider to rotate the selected colored zero set.',
    onClick: () => selectPlane(name)
  });
}

function applyCamera() {
  let target = [0, 0, 0];
  let hf = 0.78;
  if (source.layout === 'a') { target = [-4.55, 0, 0]; hf = 0.58; }
  if (source.layout === 'b') { target = [-1.35, 0, 0]; hf = 0.62; }
  if (source.layout === 'c') { target = [2.35, 0, 0]; hf = 0.70; }
  setCameraView({
    projection: 'oblique',
    obliqueAngleDeg: 45,
    depthScale: 0.66,
    target,
    heightFraction: hf,
    distanceScale: 1.1
  });
}

applyCamera();

