function setLabelVisible(keys, on) {
  for (const k of keys) labels[k].div.style.visibility = on ? 'visible' : 'hidden';
}

function updateLayoutVisibility(refit = true) {
  const la = source.layout === 'all' || source.layout === 'a';
  const lb = source.layout === 'all' || source.layout === 'b';
  const lc = source.layout === 'all' || source.layout === 'c';

  panelA.visible = la;
  panelB.visible = lb;
  panelC.visible = lc;

  setLabelVisible(['a', 'ax1'], la);
  setLabelVisible(['b', 'bx1', 'bx2'], lb);
  setLabelVisible(['c', 'cx1', 'cx2', 'cx3'], lc);

  if (refit) applyCamera();
}

function selectPlane(name) {
  source.selected = name;
  for (const id of ['selTeal', 'selOrange', 'selGray']) document.getElementById(id).classList.remove('active');
  document.getElementById(name === 'teal' ? 'selTeal' : name === 'orange' ? 'selOrange' : 'selGray').classList.add('active');
  document.getElementById('tiltSlider').value = source.slopes[name];
  document.getElementById('tiltReadout').textContent = source.slopes[name].toFixed(1);
}

document.getElementById('layoutMode').addEventListener('change', (e) => {
  source.layout = e.target.value;
  updateLayoutVisibility(true);
});

document.getElementById('selTeal').addEventListener('click', () => selectPlane('teal'));
document.getElementById('selOrange').addEventListener('click', () => selectPlane('orange'));
document.getElementById('selGray').addEventListener('click', () => selectPlane('gray'));

document.getElementById('tiltSlider').addEventListener('input', (e) => {
  const v = Number(e.target.value);
  source.slopes[source.selected] = v;
  document.getElementById('tiltReadout').textContent = v.toFixed(1);
  refreshGeometry();
});

document.getElementById('resetSource').addEventListener('click', () => {
  source.slopes.teal = 0;
  source.slopes.orange = 0;
  source.slopes.gray = 0;
  source.layout = 'all';
  document.getElementById('layoutMode').value = 'all';
  refreshGeometry();
  selectPlane('teal');
  updateLayoutVisibility(true);
});

